"""Per-language configuration: alphabet (lowercase letters accepted as 'plain' words),
vowel letters, how to treat <y>, and 'modifier' letters that carry no segment of their own
(Cyrillic soft/hard signs). CV classification is letter based (beta)."""

import indic

LATIN = "abcdefghijklmnopqrstuvwxyz"

def latin(extra="", drop=""):
    return "".join(c for c in LATIN if c not in drop) + extra

# vowels: base vowels are matched after stripping diacritics (NFD), plus extra vowel letters
